<div class="card"><h2>Locker Inventory & Monthly Charge</h2><div class="tablewrap"><table><thead><tr><th>Branch</th><th>Locker</th><th>Location</th><th>Monthly Charge</th><th>Status</th><th>Update</th></tr></thead><tbody>@forelse($lockers as $locker)<tr><td>{{ $locker->branch?->name }}</td><td><strong>{{ $locker->locker_no }}</strong></td><td>{{ $locker->location ?: '—' }}</td><td>₹{{ number_format((float)$locker->monthly_charge,2) }}</td><td><span class="badge {{ $locker->status?'':'off' }}">{{ $locker->status?'Active':'Disabled' }}</span>@if($locker->active_allocations_count>0)<div class="muted">Currently occupied</div>@endif</td><td><form class="inline" method="POST" action="{{ route('admin.lockers.update',$locker) }}">@csrf @method('PATCH')<input name="locker_no" value="{{ $locker->locker_no }}" size="8" required><input name="location" value="{{ $locker->location }}" placeholder="Location" size="12"><input type="number" step="0.01" min="0" name="monthly_charge" value="{{ $locker->monthly_charge }}" style="width:95px" required><select name="status"><option value="1" @selected($locker->status)>Active</option><option value="0" @selected(!$locker->status)>Disabled</option></select><button class="btn" type="submit">Save</button></form></td></tr>@empty<tr><td colspan="6">No lockers configured yet.</td></tr>@endforelse</tbody></table></div></div>
<div class="card"><h2>Locker Allocations</h2><div class="tablewrap"><table><thead><tr><th>Student</th><th>Locker</th><th>Period</th><th>Charge</th><th>Status / Action</th></tr></thead><tbody>@forelse($allocations as $allocation)<tr><td><strong>{{ $allocation->student?->name }}</strong><div class="muted">{{ $allocation->student?->student_code }}</div></td><td>{{ $allocation->locker?->locker_no }}<div class="muted">{{ $allocation->locker?->location }}</div></td><td>{{ $allocation->allocated_from?->format('d M Y') }} — {{ $allocation->allocated_to?->format('d M Y') ?? 'Open ended' }}</td><td>₹{{ number_format((float)$allocation->monthly_charge,2) }}/month</td><td><form class="inline" method="POST" action="{{ route('admin.lockers.allocations.update',$allocation) }}">@csrf @method('PATCH')<select name="status"><option value="reserved" @selected($allocation->status==='reserved')>Reserved</option><option value="active" @selected($allocation->status==='active')>Active</option><option value="completed" @selected($allocation->status==='completed')>Completed</option><option value="cancelled" @selected($allocation->status==='cancelled')>Cancelled</option></select><input type="date" name="allocated_to" value="{{ $allocation->allocated_to?->toDateString() }}"><input name="remarks" value="{{ $allocation->remarks }}" placeholder="Remarks"><button class="btn" type="submit">Update</button></form></td></tr>@empty<tr><td colspan="5">No locker allocations yet.</td></tr>@endforelse</tbody></table></div>{{ $allocations->links() }}</div>
